n:absolute;left:4.2%;bottom:8.3%;width:205px}.stat-label{font:10px var(--mono);letter-spacing:1.8px;color:#c0c8cc;margin-bottom:7px}.stat-label span{float:right;color:var(--white);font-size:12px}.health-track,.shield-track{height:5px;background:rgba(210,230,232,.16);margin-bottom:13px;transform:skewX(-18deg)}.health-track span,.shield-track span{height:100%;width:100%;display:block;background:var(--cyan);box-shadow:0 0 14px rgba(104,244,227,.45);transition:width .18s}.shield-track{height:3px}.shield-track span{background:#77a9ff;box-shadow:0 0 12px #4776ee}.shield-label{color:#8f9cb4}.hud-center{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:36px;height:36px}.crosshair{position:absolute;inset:0}.crosshair i{position:absolute;background:rgba(235,255,253,.92);box-shadow:0 0 5px rgba(104,244,227,.6)}.crosshair i:nth-child(1){width:2px;height:7px;top:0;left:17px}.crosshair i:nth-child(2){width:2px;height:7px;bottom:0;left:17px}.crosshair i:nth-child(3){width:7px;height:2px;left:0;top:17px}.crosshair i:nth-child(4){width:7px;height:2px;right:0;top:17px}.crosshair b{position:absolute;width:3px;height:3px;left:16.5px;top:16.5px;border-radius:50%;background:var(--cyan)}.hit-marker{position:absolute;inset:-10px;color:var(--cyan);font:32px var(--display);text-align:center;opacity:0;transform:scale(.7);transition:.08s}.hit-marker.active{opacity:1;transform:scale(1)}.hud-right{position:absolute;right:4.2%;top:15%;text-align:right}.frag-count{display:flex;align-items:baseline;gap:8px;justify-content:flex-end;color:var(--cyan);font:42px/.9 var(--display);font-weight:700}.frag-count small{font:9px var(--mono);letter-spacing:1.5px;color:#bac4c9}.enemy-count{font:9px var(--mono);color:#c0c9cd;letter-spacing:1.3px;margin-top:12px}.enemy-dot{display:inline-block;width:6px;height:6px;background:var(--orange);border-radius:50%;margin-right:6px;box-shadow:0 0 8px var(--orange)}.weapon-panel{position:absolute;right:4.2%;bottom:8%;text-align:right}.weapon-name{display:flex;align-items:center;justify-content:flex-end;gap:10px;font:22px var(--display);letter-spacing:1.5px;font-weight:700}.weapon-name small{font:10px var(--mono);color:var(--cyan);border:1px solid rgba(104,244,227,.35);padding:4px 5px}.weapon-sub{font:9px var(--mono);letter-spacing:1.4px;color:#9daab0;margin-top:3px}.weapon-keys{display:flex;justify-content:flex-end;gap:4px;margin-top:10px}.weapon-keys span{font:10px var(--mono);color:#839199;padding:4px 7px;border:1px solid rgba(215,237,239,.16)}.weapon-keys span.active{color:var(--cyan);border-color:rgba(104,244,227,.65);background:rgba(104,244,227,.09)}.speed-readout{position:absolute;left:50%;bottom:8%;transform:translateX(-50%);text-align:center;color:var(--cyan);font:28px/.9 var(--display);font-weight:700;letter-spacing:2px;text-shadow:0 0 18px rgba(104,244,227,.4)}.speed-readout small{display:block;color:#a6b0b4;font:8px var(--mono);letter-spacing:1.8px;margin-top:5px}.toast{position:absolute;top:21%;left:50%;transform:translateX(-50%);font:11px var(--mono);letter-spacing:2px;color:var(--cyan);text-shadow:0 0 12px var(--cyan);opacity:0;transition:opacity .2s}.toast.show{opacity:1}.screen{position:absolute;inset:0;z-index:5;display:none;background:linear-gradient(90deg,rgba(5,9,16,.91) 0%,rgba(5,9,16,.76) 42%,rgba(5,9,16,.14) 100%);align-items:center;padding:11% 10.2% 8%}.screen.visible{display:flex}.hero-copy{width:55%;max-width:620px;position:relative;z-index:2}.eyebrow{font:10px var(--mono);letter-spacing:2.6px;color:var(--cyan);display:flex;align-items:center;gap:9px}.eyebrow span{width:20px;height:1px;background:var(--cyan)}h1{font:clamp(72px,10.4vw,145px)/.79 var(--display);letter-spacing:-2px;margin:27px 0 22px;font-weight:900}h1 em{font-style:normal;color:var(--cyan);text-shadow:0 0 45px rgba(104,244,227,.18)}.hero-copy p{max-width:380px;color:#b1bac1;font-size:13px;line-height:1.8;margin:0 0 25px}.primary-button{position:relative;border:0;background:var(--cyan);color:#071310;padding:15px 20px;font: