ition:absolute;inset:14px 18px;background:rgba(255,255,255,.45);clip-path:polygon(50% 0,100% 100%,0 100%)}.card-cross{position:absolute;color:var(--cyan);font:16px var(--mono);top:35px;right:39px}.card-footer{border-top:1px solid rgba(139,206,214,.14);color:#86969d}.card-footer b{color:var(--cyan);font-weight:400}.start-bottom{position:absolute;bottom:4%;left:4.2%;right:4.2%;display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:2px;color:#839097}.start-bottom b{color:var(--cyan);font-size:14px;margin-left:8px}.end-card{max-width:460px;margin:auto;text-align:center;padding:40px 50px;background:rgba(6,14,22,.86);border:1px solid rgba(104,244,227,.25);backdrop-filter:blur(16px)}.end-card .eyebrow{justify-content:center}.end-card h2{font:70px/.9 var(--display);margin:18px 0;color:var(--cyan)}.end-card p{color:#abb7bc}.end-stats{display:flex;justify-content:center;gap:50px;margin:26px 0}.end-stats div{display:grid;gap:4px}.end-stats b{font:34px var(--display);color:var(--white)}.end-stats span{font:9px var(--mono);letter-spacing:1.6px;color:#90a0a5}.mobile-controls{display:none;position:absolute;inset:0;z-index:4;pointer-events:none}.move-pad{position:absolute;left:24px;bottom:35px;width:132px;height:132px;pointer-events:auto}.pad-ring{position:absolute;inset:5px;border-radius:50%;border:1px solid rgba(174,245,237,.38);background:rgba(6,18,26,.28);box-shadow:inset 0 0 24px rgba(104,244,227,.08)}.pad-ring:before,.pad-ring:after{content:"";position:absolute;background:rgba(104,244,227,.14)}.pad-ring:before{left:50%;top:10%;bottom:10%;width:1px}.pad-ring:after{top:50%;left:10%;right:10%;height:1px}.pad-knob{position:absolute;width:46px;height:46px;left:50%;top:50%;margin:-23px;border:1px solid rgba(104,244,227,.7);border-radius:50%;background:rgba(104,244,227,.26);box-shadow:0 0 20px rgba(104,244,227,.25)}.move-pad>span{position:absolute;bottom:-13px;left:0;right:0;text-align:center;font:8px var(--mono);letter-spacing:2px;color:rgba(222,246,242,.68)