import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';
const canvas=document.querySelector('#game'), isTouch=matchMedia('(pointer: coarse)').matches||'ontouchstart'in window;
let renderer,scene,camera;
try{renderer=new THREE.WebGLRenderer({canvas,antialias:!isTouch,alpha:false,powerPreference:'high-performance'})}catch(e){document.querySelector('#start-screen').innerHTML='<div class="hero-copy"><div class="eyebrow">WEBGL UNAVAILABLE</div><h1>CAN’T LOAD<br><em>THE ARENA.</em></h1><p>This browser could not create a WebGL renderer. Try a current browser with WebGL enabled.</p></div>';throw e}
renderer.setPixelRatio(Math.min(devicePixelRatio||1,isTouch?1.35:1.7));renderer.setSize(innerWidth,innerHeight,false);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
scene=new THREE.Scene();scene.background=new THREE.Color('#09131d');scene.fog=new THREE.FogExp2('#09131d',.014);camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.08,140);camera.rotation.order='YXZ';
