const M={floor:mat('#172633',.92,.12),wall:mat('#1b2b39',.72,.3),dark:mat('#0b151f',.62,.35),metal:mat('#344858',.44,.68),cyan:mat('#48dacb',.32,.35,{emissive:'#14594f',emissiveIntensity:.65}),orange:mat('#ff7959',.34,.25,{emissive:'#a92918',emissiveIntensity:.7}),white:mat('#a6fff0',.25,.1,{emissive:'#55e9d8',emissiveIntensity:1.1}),enemy:mat('#702c2b',.48,.35,{emissive:'#691d19',emissiveIntensity:.35}),enemyLight:mat('#ff654e',.28,.25,{emissive:'#ff3b22',emissiveIntensity:1.4}),blue:mat('#3964a0',.4,.45,{emissive:'#173b72',emissiveIntensity:.55})};
scene.add(new THREE.HemisphereLight('#a3e6ee','#111824',1.45));const key=new THREE.DirectionalLight('#c6fff0',2.2);key.position.set(-8,18,4);scene.add(key);const fill=new THREE.PointLight('#358eaa',32,44);fill.position.set(0,8,0);scene.add(fill);const warm=new THREE.PointLight('#ff563e',18,35);warm.position.set(-16,6,-14);scene.add(warm);
const world=new THREE.Group();scene.add(world);const platforms=[];const solidMeshes=[];
function box(name,x,y,z,w,h,d,material,opts={}){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);mesh.position.set(x,y,z);if(opts.rx)mesh.rotation.x=opts.rx;if(opts.rz)mesh.rotation.z=opts.rz;mesh.castShadow=false;mesh.receiveShadow=false;mesh.name=name;world.add(mesh);if(opts.solid)solidMeshes.push(mesh);return mesh}
function glowBar(x,y,z,w,h,d,material=M.cyan){return box('light',x,y,z,w,h,d,material)}
// Arena floor, raised platforms and bridge network.
box('arena floor',0,-.55,0,48,1,48,M.floor,{solid:true});
platforms.push({x:0,z:0,w:48,d:48,y:0});
const deck=(x,z,w,d,y,accent=M.cyan)=>{box('deck',x,y-.22,z,w,.44,d,M.wall,{solid:true});box('deck cap',x,y+.015,z,w-.22,.07,d-.22,M.metal);platforms.push({x,z,w:w-.22,d:d-.22,y:y+.05});
  box('edge',x,y-.08,z-d/2+.12,w-.5,.07,.08,accent);box('edge',x,y-.08,z+d/2-.12,w-.5,.07,.08,accent);box('edge',x-w/2+.12,y-.08,z,.08,.07,d-.5,accent);box('edge',x+w/2-.12,y-.08,z,.08,.07,d-.5,accent)};
