deck(0,-14,9,5,7.2);deck(0,14,9,5,7.2,M.orange);deck(-14,0,5,9,7.2);deck(14,0,5,9,7.2);
deck(0,0,8,8,3.2);deck(-7,0,7,3,5.25);deck(7,0,7,3,5.25,M.orange);deck(0,-7,3,7,5.25);deck(0,7,3,7,5.25,M.orange);
// Stepped side structures and chunky supports give the arena a readable vertical silhouette.
for(const x of [-18,18])for(const z of [-17,17]){box('pillar',x,3.2,z,2.4,6.4,2.4,M.dark);box('pillar cap',x,6.45,z,2.7,.18,2.7,M.metal);glowBar(x,3.2,z-1.23,.08,5.8,.07,M.cyan)}
for(const [x,z] of [[-13,-12],[13,-12],[-13,12],[13,12]]){box('support',x,1.8,z,1.2,3.6,1.2,M.dark);box('support',x,3.5,z,1.5,.18,1.5,M.metal)}
// ramps as visible approach geometry.
for(const [x,z,rz,rx] of [[-8,-10,-.3,0],[8,-10,.3,0],[-8,10,.3,0],[8,10,-.3,0]]){box('ramp',x,1.65,z,7,.35,3,M.metal,{rz});box('ramp glow',x,1.82,z,6.7,.06,.09,M.cyan,{rz})}
// Walls, seams, floor markings and overhead ring.
